import{_ as a,a as s}from"./chunks/image (125).Drxjr1IW.js";import{_ as n,o as t,c as r,a2 as o}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"Tradeboard Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"openalgo-architecture.md","filePath":"openalgo-architecture.md"}'),i={name:"openalgo-architecture.md"};function d(p,e,l,c,h,u){return t(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="tradeboard-architecture" tabindex="-1">Tradeboard Architecture <a class="header-anchor" href="#tradeboard-architecture" aria-label="Permalink to &quot;Tradeboard Architecture&quot;">​</a></h1><p>Tradeboard is a self-hosted Flask application with a React frontend. Everything runs on your machine: the web UI, the REST API, the WebSocket proxy, the strategy host, and the databases. No trading data leaves your infrastructure.</p><p>This page explains how the pieces fit together. For component-level detail, see the <a href="./developers/design-documentation/README.html">Design Documentation</a>.</p><hr><h2 id="the-layered-view" tabindex="-1">The Layered View <a class="header-anchor" href="#the-layered-view" aria-label="Permalink to &quot;The Layered View&quot;">​</a></h2><p>Every client speaks the same Tradeboard API. The service layer holds the business logic, and a broker plugin translates it to whatever the broker actually expects.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────────┐ ┌───────────────┐ ┌───────────────┐ ┌───────────────┐</span></span>
<span class="line"><span>│  TradingView  │ │   Amibroker   │ │     Excel     │ │     Python    │</span></span>
<span class="line"><span>└───────────────┘ └───────────────┘ └───────────────┘ └───────────────┘</span></span>
<span class="line"><span>        │                 │                 │                 │</span></span>
<span class="line"><span>        └─────────────────┴─────────────────┴─────────────────┘</span></span>
<span class="line"><span>                                   │</span></span>
<span class="line"><span>                                   ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│        Flask App: blueprints, REST API v1, auth, rate limits        │</span></span>
<span class="line"><span>│                  CORS, CSP, CSRF, TOTP, audit trail                 │</span></span>
<span class="line"><span>└──────────────────────────────────┬──────────────────────────────────┘</span></span>
<span class="line"><span>                                   │</span></span>
<span class="line"><span>                                   ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                            Service Layer                            │</span></span>
<span class="line"><span>│         orders, data, options, sandbox, calendar, messaging         │</span></span>
<span class="line"><span>└──────────────────────────────────┬──────────────────────────────────┘</span></span>
<span class="line"><span>                                   │</span></span>
<span class="line"><span>                                   ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                       Broker Plugin Interface                       │</span></span>
<span class="line"><span>│            normalised symbols, orders, quotes and streams           │</span></span>
<span class="line"><span>└──────────────────────────────────┬──────────────────────────────────┘</span></span>
<span class="line"><span>                                   │</span></span>
<span class="line"><span>                                   ▼</span></span>
<span class="line"><span>┌─────────┐ ┌─────────┐ ┌─────────┐ ┌─────────┐ ┌─────────┐ ┌─────────┐</span></span>
<span class="line"><span>│ Zerodha │ │  Angel  │ │   Dhan  │ │  Fyers  │ │  Upstox │ │   More  │</span></span>
<span class="line"><span>└─────────┘ └─────────┘ └─────────┘ └─────────┘ └─────────┘ └─────────┘</span></span></code></pre></div><p>The point of the plugin boundary is that your strategy never changes when your broker does. Symbols, order types, quotes and streams are normalised on the way down, and broker responses are normalised on the way back up.</p><hr><h2 id="processes-and-ports" tabindex="-1">Processes and Ports <a class="header-anchor" href="#processes-and-ports" aria-label="Permalink to &quot;Processes and Ports&quot;">​</a></h2><p>Tradeboard runs as two listeners.</p><table tabindex="0"><thead><tr><th>Process</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Flask application</strong></td><td><code>127.0.0.1:5000</code></td><td>Web UI, REST API v1, webhooks, broker OAuth callbacks</td></tr><tr><td><strong>WebSocket proxy</strong></td><td><code>127.0.0.1:8765</code></td><td>Market data streaming and order updates</td></tr></tbody></table><p>Hosted Python strategies run in <strong>separate processes</strong>, so a strategy that crashes or blocks cannot take the platform down with it.</p><hr><h2 id="request-lifecycle-placing-an-order" tabindex="-1">Request Lifecycle: Placing an Order <a class="header-anchor" href="#request-lifecycle-placing-an-order" aria-label="Permalink to &quot;Request Lifecycle: Placing an Order&quot;">​</a></h2><p>Whether the signal comes from a TradingView webhook, the Python SDK, an Excel cell, or the built-in terminal, it follows the same path.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│           Signal arrives (webhook, SDK, sheet or terminal)          │</span></span>
<span class="line"><span>└──────────────────────────────────┬──────────────────────────────────┘</span></span>
<span class="line"><span>                                   │</span></span>
<span class="line"><span>                                   ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│             API key check, schema validation, rate limit            │</span></span>
<span class="line"><span>└──────────────────────────────────┬──────────────────────────────────┘</span></span>
<span class="line"><span>                                   │</span></span>
<span class="line"><span>                                   ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│         Analyzer mode? Yes: sandbox store. No: broker plugin        │</span></span>
<span class="line"><span>└──────────────────────────────────┬──────────────────────────────────┘</span></span>
<span class="line"><span>                                   │</span></span>
<span class="line"><span>                                   ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│         Broker plugin maps symbol and order to broker format        │</span></span>
<span class="line"><span>└──────────────────────────────────┬──────────────────────────────────┘</span></span>
<span class="line"><span>                                   │</span></span>
<span class="line"><span>                                   ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│          Order sent, response normalised, order id returned         │</span></span>
<span class="line"><span>└──────────────────────────────────┬──────────────────────────────────┘</span></span>
<span class="line"><span>                                   │</span></span>
<span class="line"><span>                                   ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│        Event published: Telegram, WhatsApp, logs, PnL update        │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>Two things in that chain are worth calling out.</p><p><strong>Analyzer mode is a real fork in the path.</strong> When it is on, the order stops at the sandbox store and never reaches the broker, while market prices still come from live broker data. This is what makes it safe to test a strategy end to end. See <a href="./new-features/api-analyzer.html">API Analyzer</a>.</p><p><strong>The event bus is how everything else stays in sync.</strong> Order placement publishes an event that the Telegram and WhatsApp subscribers, the logging subscriber, the strategy book, and the WebSocket proxy all listen to independently. Adding a notification channel does not mean touching the order path.</p><hr><h2 id="market-data-one-upstream-many-consumers" tabindex="-1">Market Data: One Upstream, Many Consumers <a class="header-anchor" href="#market-data-one-upstream-many-consumers" aria-label="Permalink to &quot;Market Data: One Upstream, Many Consumers&quot;">​</a></h2><p>The WebSocket proxy holds <strong>one connection to the broker feed</strong> and fans it out to every consumer. Ten strategies watching NIFTY do not open ten broker connections.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│          Broker market data feed (one upstream connection)          │</span></span>
<span class="line"><span>└──────────────────────────────────┬──────────────────────────────────┘</span></span>
<span class="line"><span>                                   │</span></span>
<span class="line"><span>                                   ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                     WebSocket Proxy on port 8765                    │</span></span>
<span class="line"><span>│             adapter, connection manager, broadcast layer            │</span></span>
<span class="line"><span>└───────┬─────────────────┬─────────────────┬─────────────────┬───────┘</span></span>
<span class="line"><span>        │                 │                 │                 │</span></span>
<span class="line"><span>        ▼                 ▼                 ▼                 ▼</span></span>
<span class="line"><span>┌───────────────┐ ┌───────────────┐ ┌───────────────┐ ┌───────────────┐</span></span>
<span class="line"><span>│     Excel     │ │     Python    │ │    Browser    │ │      Flow     │</span></span>
<span class="line"><span>└───────────────┘ └───────────────┘ └───────────────┘ └───────────────┘</span></span></code></pre></div><p>Each consumer subscribes to the symbols and mode it wants (LTP, quote, or depth). The proxy handles broker-specific adapter logic, reconnection, and subscription bookkeeping, so consumers see one protocol regardless of broker. See <a href="./developers/design-documentation/authentication-platforms.html">WebSockets</a>.</p><hr><h2 id="code-layout" tabindex="-1">Code Layout <a class="header-anchor" href="#code-layout" aria-label="Permalink to &quot;Code Layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Directory</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>blueprints/</code></td><td>Flask route modules, one per feature area, roughly 60 of them</td></tr><tr><td><code>restx_api/</code></td><td>The versioned REST API surface and its request schemas</td></tr><tr><td><code>services/</code></td><td>Business logic, around 80 modules, shared by the API and the UI</td></tr><tr><td><code>broker/</code></td><td>36 broker plugins, each with its own <code>api/</code> and <code>mapping/</code></td></tr><tr><td><code>websocket_proxy/</code></td><td>Streaming server, broker adapters, connection manager</td></tr><tr><td><code>database/</code></td><td>SQLAlchemy models and per-domain data access</td></tr><tr><td><code>sandbox/</code></td><td>Analyzer mode: simulated execution, margin, positions</td></tr><tr><td><code>events/</code>, <code>subscribers/</code></td><td>In-process event bus and its listeners</td></tr><tr><td><code>strategies/</code>, <code>portfolio/</code>, <code>sip/</code></td><td>Strategy hosting, portfolio and SIP backtesting</td></tr><tr><td><code>mcp/</code></td><td>Model Context Protocol server for AI agents</td></tr><tr><td><code>frontend/</code></td><td>React and Vite single page application</td></tr><tr><td><code>utils/</code></td><td>Shared helpers, HTTP connection pooling, constants</td></tr></tbody></table><p>The <code>restx_api/</code> schemas are the contract. They validate every incoming request and reject unknown fields, so a malformed payload fails fast with a clear message rather than reaching a broker.</p><hr><h2 id="data-stores" tabindex="-1">Data Stores <a class="header-anchor" href="#data-stores" aria-label="Permalink to &quot;Data Stores&quot;">​</a></h2><p>Tradeboard splits its data across several SQLite databases so that heavy write paths do not contend with trading data, plus DuckDB for historical bars.</p><table tabindex="0"><thead><tr><th>Store</th><th>Holds</th></tr></thead><tbody><tr><td><code>db/tradeboard.db</code></td><td>Users, API keys, broker auth, symbols, strategies, settings</td></tr><tr><td><code>db/latency.db</code></td><td>Order round-trip timings</td></tr><tr><td><code>db/logs.db</code></td><td>Traffic logs: request metadata, status, duration</td></tr><tr><td><code>db/sandbox.db</code></td><td>Analyzer mode orders, positions, and funds</td></tr><tr><td><code>db/health.db</code></td><td>System health monitoring</td></tr><tr><td>DuckDB (Historify)</td><td>Historical OHLCV bars, stored columnar for fast range queries</td></tr></tbody></table><hr><h2 id="security-boundaries" tabindex="-1">Security Boundaries <a class="header-anchor" href="#security-boundaries" aria-label="Permalink to &quot;Security Boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Control</th></tr></thead><tbody><tr><td>Session login</td><td>TOTP two-factor, rate-limited login attempts</td></tr><tr><td>API requests</td><td>API key resolved server-side, never a broker token from the client</td></tr><tr><td>Key storage</td><td>Argon2 hashing plus a separately encrypted retrieval copy</td></tr><tr><td>Browser</td><td>CORS policy, CSP headers, CSRF tokens</td></tr><tr><td>Throughput</td><td>Per-endpoint rate limits, defaulting to 50 requests per second overall and 10 per second for orders</td></tr><tr><td>Strategies</td><td>Hosted scripts run in isolated processes</td></tr><tr><td>Audit</td><td>Full request and order audit trail</td></tr></tbody></table><p>Broker credentials never reach the client. A strategy holds an <strong>Tradeboard API key</strong>, and the server resolves that to the active broker session, so revoking a key does not require touching your broker account. See <a href="./developers/design-documentation/database-layer.html">Security</a>.</p><hr><h2 id="hosting-topologies" tabindex="-1">Hosting Topologies <a class="header-anchor" href="#hosting-topologies" aria-label="Permalink to &quot;Hosting Topologies&quot;">​</a></h2><h3 id="windows-and-mac-hosting-architecture" tabindex="-1">Windows and Mac Hosting Architecture <a class="header-anchor" href="#windows-and-mac-hosting-architecture" aria-label="Permalink to &quot;Windows and Mac Hosting Architecture&quot;">​</a></h3><figure><img src="`+a+'" alt=""><figcaption></figcaption></figure><h3 id="linux-server-hosting-architecture" tabindex="-1">Linux Server Hosting Architecture <a class="header-anchor" href="#linux-server-hosting-architecture" aria-label="Permalink to &quot;Linux Server Hosting Architecture&quot;">​</a></h3><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><p>A local install is the simplest and keeps everything on your desktop. A server install suits strategies that must run when your desktop does not. A public deployment still requires you to configure TLS, a reverse proxy, firewall rules, secrets, and an update process correctly. See <a href="./getting-started/README.html">Getting Started</a>.</p><hr><h2 id="related-reading" tabindex="-1">Related Reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related Reading&quot;">​</a></h2><ul><li><a href="./developers/design-documentation/README.html">Design Documentation</a> for the component-by-component breakdown</li><li><a href="./developers/design-documentation/19-placeorder-call-flow.html">Place Order Call Flow</a> for the order path in detail</li><li><a href="./developers/design-documentation/27-service-layer.html">Service Layer</a> and <a href="./developers/design-documentation/18-database-structure.html">Database Structure</a></li><li><a href="./api-documentation/v1/README.html">API Documentation</a> for the REST and WebSocket surface</li><li><a href="./why-to-build-with-tradeboard.html">Why to Build with Tradeboard?</a> for the rationale</li></ul>',47)])])}const y=n(i,[["render",d]]);export{m as __pageData,y as default};
